/// One script's vector.
struct Vector {
    name: String,
    script: Value,
    results: Vec<Value>,
    export_sha256: String,
    export_msha256: String,
    /// The generated vectors' `covered_digest` of Go's export.
    covered: String,
}

fn body_sha256(text: &str) -> String {
    let mut h = Sha256::new();
    for l in text.lines().filter(|l| !l.starts_with('#')) {
        h.update(l.as_bytes());
        h.update(b"\n");
    }
    h.finalize().iter().fold(String::new(), |mut s, b| {
        let _ = write!(s, "{b:02x}");
        s
    })
}

fn header(text: &str, key: &str) -> String {
    text.lines()
        .find_map(|l| l.strip_prefix(key))
        .map(str::trim)
        .unwrap_or_else(|| panic!("no {key:?} header"))
        .to_owned()
}

fn read_vectors() -> Vec<Vector> {
    read_vector_file(VECTORS, ENTRIES)
}

fn read_vector_file(file: &str, pinned: usize) -> Vec<Vector> {
    let text = std::fs::read_to_string(data_dir().join(file)).expect("read vectors");
    assert_eq!(
        body_sha256(&text),
        header(&text, "# body-sha256:"),
        "body hash"
    );
    let mut out: Vec<Vector> = Vec::new();
    for line in text.lines().filter(|l| !l.starts_with('#')) {
        let (kind, rest) = line.split_once(' ').expect("tagged line");
        match kind {
            "name" => out.push(Vector {
                name: rest.to_owned(),
                script: Value::Null,
                results: Vec::new(),
                export_sha256: String::new(),
                export_msha256: String::new(),
                covered: String::new(),
            }),
            "script" => {
                out.last_mut().expect("name first").script =
                    serde_json::from_str(rest).expect("script JSON")
            }
            "result" => out
                .last_mut()
                .expect("name first")
                .results
                .push(serde_json::from_str(rest).expect("result JSON")),
            "export" => {
                let (a, b) = rest.split_once(' ').expect("two digests");
                let v = out.last_mut().expect("name first");
                v.export_sha256 = a.to_owned();
                v.export_msha256 = b.to_owned();
            }
            "covered" => out.last_mut().expect("name first").covered = rest.to_owned(),
            other => panic!("{file}: unexpected line kind {other:?}"),
        }
    }
    let entries: usize = out.iter().map(|v| v.results.len()).sum();
    assert_eq!(
        entries,
        header(&text, "# entries:").parse::<usize>().expect("count")
    );
    assert_eq!(entries, pinned, "{file}: pinned entry count");
    let mut counts = BTreeMap::new();
    for l in text.lines() {
        if let Some(rest) = l.strip_prefix("# scripts: ") {
            counts.insert("scripts", rest.trim().parse::<usize>().expect("count"));
        }
    }
    assert_eq!(counts.get("scripts"), Some(&out.len()), "script count");
    out
}

fn export_text(name: &str) -> String {
    std::fs::read_to_string(data_dir().join("opvectors").join(format!("{name}.pe")))
        .unwrap_or_else(|e| panic!("{name}.pe: {e}"))
}

#[test]
fn replay_frozen_vectors() {
    for v in read_vectors() {
        let go_pe = export_text(&v.name);
        let go = purse_export_check::parse(&go_pe).expect("Go export parses");
        assert_eq!(go.sha256, v.export_sha256, "{}: export digest", v.name);
        assert_eq!(go.msha256, v.export_msha256, "{}: masked digest", v.name);
        let dir = scratch("frozen");
        let rust = runner::run(&v.script, &dir).unwrap_or_else(|e| panic!("{}: {e}", v.name));
        assert_eq!(
            rust.results.len(),
            v.results.len(),
            "{}: record count",
            v.name
        );
        for (g, r) in v.results.iter().zip(&rust.results) {
            check_record(&v.name, g, r);
        }
        compare_checkpoints(&v.name, &frozen_checkpoints(&v), &rust.checkpoints);
        compare_exports(&v.name, &go_pe, &rust.export);
        let _ = std::fs::remove_dir_all(&dir);
    }
}

/// The frozen file of Go's export at checkpoint `cp` of script `name`.
fn checkpoint_file(name: &str, cp: &str) -> String {
    format!("{name}.{cp}.pe")
}

/// Go's checkpoint exports of a hand-written vector, in script order, each
/// checked against the digests its `rt.checkpoint` record gives.
fn frozen_checkpoints(v: &Vector) -> Vec<(String, String)> {
    v.results
        .iter()
        .filter(|r| r["op"] == "rt.checkpoint")
        .map(|r| {
            let file = r["ok"]["file"].as_str().expect("a checkpoint's file");
            let cp = file.strip_suffix(".pe").expect("a .pe file");
            // `export_text` reads `<its argument>.pe`.
            let text = export_text(&format!("{}.{cp}", v.name));
            let ex = purse_export_check::parse(&text).expect("Go export parses");
            let what = format!("{}: checkpoint {cp}", v.name);
            assert_eq!(
                Some(ex.sha256.as_str()),
                r["ok"]["sha256~cr"].as_str(),
                "{what}: digest"
            );
            assert_eq!(
                Some(ex.msha256.as_str()),
                r["ok"]["msha256~c"].as_str(),
                "{what}: masked digest"
            );
            (cp.to_owned(), text)
        })
        .collect()
}

#[test]
fn vectors_are_the_corpus_and_name_the_pin() {
    let text = std::fs::read_to_string(data_dir().join(VECTORS)).expect("read vectors");
    assert!(
        text.lines()
            .take_while(|l| l.starts_with('#'))
            .any(|l| l.contains(DCRWALLET_PARITY_COMMIT)),
        "the header names dcrwallet {DCRWALLET_PARITY_COMMIT}"
    );
    let vectors = read_vectors();
    let corpus = corpus();
    assert_eq!(
        vectors.iter().map(|v| &v.name).collect::<Vec<_>>(),
        corpus.iter().map(|(n, _)| n).collect::<Vec<_>>(),
        "one vector per hand-written script"
    );
    for (v, (_, script)) in vectors.iter().zip(&corpus) {
        assert_eq!(
            &v.script, script,
            "{}: the vector's script is the corpus file",
            v.name
        );
    }
}

/// Regenerates the vectors from the oracle, checking the Rust runner
/// agrees with every one before writing.
#[test]
#[ignore = "regenerates tests/data from the Go oracle"]
fn regenerate_frozen_vectors() {
    if std::env::var_os("PURSE_UDB_REGEN").is_none() {
        eprintln!("set PURSE_UDB_REGEN=1 to regenerate");
        return;
    }
    let Some(mut o) = oracle_or_skip("oprunner") else {
        return;
    };
    let mut body = String::new();
    let mut entries = 0usize;
    let scripts = corpus();
    std::fs::create_dir_all(data_dir().join("opvectors")).expect("mkdir");
    for (name, script) in &scripts {
        let dir = scratch("regen");
        let (results, pe) = go_run(&mut o, script, &dir.join("go"));
        let rust = runner::run(script, &dir.join("rust")).expect("Rust runner");
        for (g, r) in results.iter().zip(&rust.results) {
            check_record(name, g, r);
        }
        let checkpoints = go_checkpoints(&results, &dir.join("go"));
        compare_checkpoints(name, &checkpoints, &rust.checkpoints);
        compare_exports(name, &pe, &rust.export);
        for (cp, text) in &checkpoints {
            let mut lines = text.lines();
            let mut out = format!("{}\n", lines.next().expect("magic"));
            let _ = writeln!(
                out,
                "# Go's export at checkpoint {cp} of crates/purse-udb/tests/data/opscripts/{name}.json,"
            );
            let _ = writeln!(
                out,
                "# run by tools/oracle/cmd/oprunner; see crates/purse-udb/tests/data/{VECTORS}."
            );
            for l in lines {
                out.push_str(l);
                out.push('\n');
            }
            std::fs::write(
                data_dir().join("opvectors").join(checkpoint_file(name, cp)),
                out,
            )
            .expect("write checkpoint export");
        }
        let ex = purse_export_check::parse(&pe).expect("parse");
        let _ = writeln!(body, "name {name}");
        let _ = writeln!(
            body,
            "script {}",
            serde_json::to_string(script).expect("json")
        );
        for r in &results {
            let _ = writeln!(body, "result {}", serde_json::to_string(r).expect("json"));
        }
        let _ = writeln!(body, "export {} {}", ex.sha256, ex.msha256);
        entries += results.len();
        let mut lines = pe.lines();
        let mut out = format!("{}\n", lines.next().expect("magic"));
        let _ = writeln!(
            out,
            "# Go's final export of crates/purse-udb/tests/data/opscripts/{name}.json, run by"
        );
        let _ = writeln!(
            out,
            "# tools/oracle/cmd/oprunner; see crates/purse-udb/tests/data/{VECTORS}."
        );
        for l in lines {
            out.push_str(l);
            out.push('\n');
        }
        std::fs::write(data_dir().join("opvectors").join(format!("{name}.pe")), out)
            .expect("write export");
        let _ = std::fs::remove_dir_all(&dir);
    }
    let mut text = String::new();
    for l in [
        "# Operation-script vectors of purse-udb (records in the".to_owned(),
        "# format of docs/adr/0002-operation-script-format.md).".to_owned(),
        "#".to_owned(),
        format!(
            "# Every result line is a line of the results.jsonl that tools/oracle/cmd/oprunner, built with {REFERENCE_GO},"
        ),
        format!(
            "# wrote for the script line above it, running dcrwallet {DCRWALLET_PARITY_COMMIT}'s wallet/udb;"
        ),
        "# each export line names the eof digests (exact, masked) of Go's final export,".to_owned(),
        "# kept as tests/data/opvectors/<name>.pe, and Go's export at each checkpoint as"
            .to_owned(),
        "# tests/data/opvectors/<name>.<checkpoint>.pe. Regenerate with:".to_owned(),
        "#   PURSE_UDB_REGEN=1 PURSE_REQUIRE_ORACLE=1 cargo test -p purse-udb --test frozen \\"
            .to_owned(),
        "#       -- --ignored regenerate_frozen_vectors".to_owned(),
        "# which also checks that the Rust runner agrees. Do not edit by hand. Sealed values,"
            .to_owned(),
        "# salts and digests in the exports follow the seeded stream of each script's".to_owned(),
        "# setup.rand, so regeneration reproduces these files byte for byte.".to_owned(),
        format!("# scripts: {}", scripts.len()),
        format!("# entries: {entries}"),
    ] {
        text.push_str(&l);
        text.push('\n');
    }
    let _ = writeln!(text, "# body-sha256: {}", body_sha256(&body));
    text.push_str(&body);
    std::fs::write(data_dir().join(VECTORS), text).expect("write vectors");
    eprintln!("wrote {} scripts, {entries} result lines", scripts.len());
}

/// The frozen exports are exactly the hand-written scripts' final exports
/// and the exports of their checkpoints: no checkpoint without its file,
/// no file a script no longer makes.
#[test]
fn checkpoint_vectors_are_the_scripts_checkpoints() {
    let mut want = std::collections::BTreeSet::new();
    for (name, script) in corpus() {
        want.insert(format!("{name}.pe"));
        for op in script["ops"].as_array().expect("ops") {
            if op["op"] == "rt.checkpoint" {
                let cp = op["name"].as_str().expect("a checkpoint name");
                want.insert(checkpoint_file(&name, cp));
            }
        }
    }
    let have: std::collections::BTreeSet<String> = std::fs::read_dir(data_dir().join("opvectors"))
        .expect("opvectors")
        .map(|e| e.expect("entry").file_name().to_string_lossy().into_owned())
        .collect();
    assert_eq!(have, want, "tests/data/opvectors");
    assert!(
        want.len() > corpus().len(),
        "no hand-written script makes a checkpoint"
    );
}

/// The generated set: scripts 0 to 5 on regnet, testnet3 and mainnet (two
/// each, at most one costly scrypt operation beyond creation), the rest on
/// simnet.
fn generated_set() -> Vec<(String, Value)> {
    let mut rng = SplitMix64(GEN_SEED);
    (0..GEN_SCRIPTS)
        .map(|id| {
            let network = match id {
                0 | 1 => "regnet",
                2 | 3 => "testnet3",
                4 | 5 => "mainnet",
                _ => "simnet",
            };
            let shape = Shape {
                network: Some(network),
                costly_scrypt_ops: 1,
            };
            (format!("generated {id}"), generate(&mut rng, id, shape))
        })
        .collect()
}

#[test]
fn replay_generated_vectors() {
    replay_generated(GEN_VECTORS, GEN_ENTRIES, GEN_SCRIPTS);
}

/// The generated watching-only set: on regnet, testnet3 and mainnet one
/// script of each kind (at most one costly scrypt operation beyond
/// creation), on simnet five of each.
fn watching_set() -> Vec<(String, Value)> {
    let mut rng = SplitMix64(WO_SEED);
    let kinds = [
        WatchKind::XpubLegacy,
        WatchKind::XpubSlip0044,
        WatchKind::ConvertedLegacy,
        WatchKind::ConvertedSlip0044,
    ];
    (0..WO_SCRIPTS)
        .map(|id| {
            let network = match id / 4 {
                0 => "regnet",
                1 => "testnet3",
                2 => "mainnet",
                _ => "simnet",
            };
            let shape = Shape {
                network: Some(network),
                costly_scrypt_ops: 1,
            };
            let kind = kinds[id % 4];
            (
                format!("generated watching-only {id}"),
                generate_watching_as(&mut rng, id, network, kind, shape),
            )
        })
        .collect()
}

#[test]
fn replay_watching_only_vectors() {
    replay_generated(WO_VECTORS, WO_ENTRIES, WO_SCRIPTS);
}

/// The watching-only vectors are the set the generator makes from the
/// fixed seed.
#[test]
fn watching_only_vectors_are_the_seeded_set() {
    let vectors = read_vector_file(WO_VECTORS, WO_ENTRIES);
    let set = watching_set();
    assert_eq!(vectors.len(), set.len());
    for (v, (name, script)) in vectors.iter().zip(&set) {
        assert_eq!(&v.name, name);
        assert_eq!(
            &v.script, script,
            "{name}: the generator changed; regenerate"
        );
    }
}

/// Regenerates the watching-only vectors from the oracle, checking that
/// the Rust runner agrees with every record and export before writing.
#[test]
#[ignore = "regenerates tests/data from the Go oracle"]
fn regenerate_watching_only_vectors() {
    regenerate_generated(WO_VECTORS, &watching_set(), WO_SEED, "watching_set");
}

/// The generated passphrase set: on regnet, testnet3 and mainnet one
/// script on a seed's wallet and one on a wallet created from an account
/// extended public key (at most one costly scrypt operation beyond
/// creation), on simnet nine of each.
fn passphrase_set() -> Vec<(String, Value)> {
    let mut rng = SplitMix64(PASS_SEED);
    (0..PASS_SCRIPTS)
        .map(|id| {
            let network = match id / 2 {
                0 => "regnet",
                1 => "testnet3",
                2 => "mainnet",
                _ => "simnet",
            };
            let shape = Shape {
                network: Some(network),
                costly_scrypt_ops: 1,
            };
            (
                format!("generated passphrase {id}"),
                generate_passphrase_as(&mut rng, id, network, id % 2 == 1, shape),
            )
        })
        .collect()
}

