/// Writes a generated vector file from the oracle.
fn regenerate_generated(file: &str, set: &[(String, Value)], seed: u64, set_fn: &str) {
    if std::env::var_os("PURSE_UDB_REGEN").is_none() {
        eprintln!("set PURSE_UDB_REGEN=1 to regenerate");
        return;
    }
    let Some(mut o) = oracle_or_skip("oprunner") else {
        return;
    };
    let mut body = String::new();
    let mut entries = 0usize;
    for (name, script) in set {
        let dir = scratch("regen-gen");
        let (results, pe) = go_run(&mut o, script, &dir.join("go"));
        let rust = runner::run(script, &dir.join("rust")).expect("Rust runner");
        // Only the final export of a generated script is frozen.
        assert!(rust.checkpoints.is_empty(), "{name}: a checkpoint");
        assert_eq!(results.len(), rust.results.len(), "{name}: record count");
        for (g, r) in results.iter().zip(&rust.results) {
            check_record(name, g, r);
        }
        compare_exports(name, &pe, &rust.export);
        let _ = writeln!(body, "name {name}");
        let _ = writeln!(
            body,
            "script {}",
            serde_json::to_string(script).expect("json")
        );
        for r in &results {
            let _ = writeln!(body, "result {}", serde_json::to_string(r).expect("json"));
        }
        let _ = writeln!(body, "covered {}", covered_digest(&pe));
        entries += results.len();
        let _ = std::fs::remove_dir_all(&dir);
    }
    let mut text = String::new();
    for l in [
        format!(
            "# Generated operation-script vectors of purse-udb's {} (records in",
            if TX_FILES.contains(&file) {
                "transaction store"
            } else if file == AUX_VECTORS {
                "auxiliary records"
            } else if file == CREATION_VECTORS {
                "wallet creation"
            } else if file == PTR_VECTORS {
                "update groups"
            } else {
                "address manager"
            }
        ),
        "# the format of docs/adr/0002-operation-script-format.md).".to_owned(),
        "#".to_owned(),
        format!(
            "# The scripts are tests/support/{}'s, from the fixed seed {seed:#x}",
            if TX_FILES.contains(&file) {
                "txgen.rs"
            } else if file == AUX_VECTORS {
                "auxgen.rs"
            } else if file == PTR_VECTORS {
                "ptrgen.rs"
            } else {
                "generator.rs"
            }
        ),
        format!("# (crates/purse-udb/tests/frozen.rs, {set_fn}). Every result line is a line of"),
        format!(
            "# the results.jsonl that tools/oracle/cmd/oprunner, built with {REFERENCE_GO}, wrote"
        ),
        format!(
            "# for the script line above it, running dcrwallet {DCRWALLET_PARITY_COMMIT}'s wallet/udb;"
        ),
        "# each covered line is the SHA-256 of what the export comparison compares in Go's"
            .to_owned(),
        "# final export (tests/support/compare.rs, covered_digest: the metas, then every"
            .to_owned(),
        "# section the Rust producer covers under the masked observable profile).".to_owned(),
        "# Regenerate with:".to_owned(),
        "#   PURSE_UDB_REGEN=1 PURSE_REQUIRE_ORACLE=1 cargo test -p purse-udb --test frozen \\"
            .to_owned(),
        format!(
            "#       -- --ignored {}",
            match file {
                GEN_VECTORS => "regenerate_generated_vectors",
                WO_VECTORS => "regenerate_watching_only_vectors",
                PASS_VECTORS => "regenerate_passphrase_vectors",
                TX_VECTORS => "regenerate_txstore_vectors",
                TX_CREDIT_VECTORS => "regenerate_txstore_credit_vectors",
                TX_CMS_VECTORS => "regenerate_txstore_cms_vectors",
                TX_SELECT_VECTORS => "regenerate_txstore_select_vectors",
                AUX_VECTORS => "regenerate_aux_vectors",
                CREATION_VECTORS => "regenerate_creation_vectors",
                PTR_VECTORS => "regenerate_ptr_vectors",
                _ => "regenerate_change_vectors",
            }
        ),
        "# which also checks that the Rust runner agrees. Do not edit by hand.".to_owned(),
        format!("# scripts: {}", set.len()),
        format!("# entries: {entries}"),
    ] {
        text.push_str(&l);
        text.push('\n');
    }
    let _ = writeln!(text, "# body-sha256: {}", body_sha256(&body));
    text.push_str(&body);
    std::fs::write(data_dir().join(file), text).expect("write vectors");
    eprintln!("wrote {} scripts, {entries} result lines", set.len());
}

